// Import the Verus prelude
use verus::prelude::*;

verus! {

    /// Returns the maximum element of a non-empty vector of `usize`.
    ///
    /// Requirements:
    ///   - `lst.len() > 0`
    ///
    /// Guarantees:
    ///   - Every element of `lst` is ≤ `result`.
    ///   - There exists some index `i` with `lst[i] == result`.
    pub fn max_of_list(lst: &Vec<usize>) -> (result: usize)
        requires lst.len() > 0
        ensures forall |j: usize| j < lst.len() ==> lst[j] <= result
        ensures exists |i: usize| i < lst.len() && lst[i] == result
    {
        // Initialize:
        //   max_val = lst[0]
        //   i       = 1
        let mut max_val: usize = lst[0];
        let mut i: usize = 1;

        // Iterate from i = 1 .. lst.len(), updating max_val
        while i < lst.len()
            invariant i <= lst.len()
            // Invariant: for all indices k < i, lst[k] ≤ max_val
            invariant forall |k: usize| k < i ==> lst[k] <= max_val
            // We are making progress because i increases each loop
            decreases lst.len() - i
        {
            if lst[i] > max_val {
                max_val = lst[i];
            }
            i += 1;
        }

        // At termination, i == lst.len()
        // By the loop invariant, every lst[k] for k < lst.len() is ≤ max_val,
        // and by construction, some index attained max_val.
        max_val
    }

} // end of `verus!`